        dtdload: true,
      });

      const root = doc.root();
      if (!root || root.name() !== "order") {
        return NextResponse.json(
          {
            error: "Invalid XML structure. Expected root element <order>.",
            debug: {
              config: SUPPLIER_REGISTRY_PATH,
