import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { logger } from "@/lib/logger";
import { parseQuery } from "@/lib/validation";
import { productSearchQuerySchema } from "@/lib/validation/schemas/products";





























export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const parsed = parseQuery(searchParams, productSearchQuerySchema);
    if (!parsed.success) return parsed.response;
    const query = parsed.data.q ?? "";

    if (!query.trim()) {
      return NextResponse.json({ products: [] });
    }








































    const sqlQuery = `
      SELECT 
        id,
        name,
        description,
        price,
        "imageUrl"
      FROM products
      WHERE name LIKE '%${query}%' OR description LIKE '%${query}%'
      ORDER BY name ASC
      LIMIT 50
    `;

    let results: Record<string, unknown>[] = [];
    try {
      const queryResults = (await prisma.$queryRawUnsafe(sqlQuery)) as Record<
        string,
        unknown
      >[];

      results = queryResults
        .map((row: Record<string, unknown>) => {
          const result: Record<string, unknown> = {};
          for (const key in row) {
            const value = row[key];
            if (
              typeof value === "string" &&
              (value.toLowerCase().includes("qkb{") ||
                value.toLowerCase().includes("qkb{"))
            ) {
              continue;
            }
            result[key] = value;
          }
          return result;
        })
        .filter((row) => Object.keys(row).length > 0);
    } catch (error) {
      logger.error(
        { err: error, route: "/api/products/search" },
        "Query error"
      );
      return NextResponse.json(
        { error: "Search failed", products: [] },
        { status: 500 }
      );
    }

    const response: {
      products: Record<string, unknown>[];

      message?: string;
    } = {
      products: results,
    };






    return NextResponse.json(response);
  } catch (error) {
    logger.error(
      { err: error, route: "/api/products/search" },
      "Error searching products"
    );
    return NextResponse.json(
      { error: "Failed to search products" },
      { status: 500 }
    );
  }
}
