import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { withAdminAuth } from "@/lib/server-auth";
import Database from "better-sqlite3";
import { getDatabaseUrl } from "@/lib/database";
import { logger } from "@/lib/logger";
import { parseQuery } from "@/lib/validation";
import { reviewsAuditQuerySchema } from "@/lib/validation/schemas/admin";





























function getDbPath(): string {
  const url = getDatabaseUrl();
  return url.replace(/^file:/, "");
}

export const GET = withAdminAuth(
  async (request: NextRequest, _context, _user) => {
    try {
      const { searchParams } = new URL(request.url);
      const parsed = parseQuery(searchParams, reviewsAuditQuerySchema);
      if (!parsed.success) return parsed.response;
      const authorFilter = parsed.data.author ?? null;

      const authors = await prisma.review.findMany({
        select: { author: true },
        distinct: ["author"],
        orderBy: { author: "asc" },
      });

      const distinctAuthors = authors.map((a) => a.author);










































      let reviews: Record<string, unknown>[];

      if (authorFilter) {
        const query = `
        SELECT
          r.id,
          r."productId",
          r.content,
          r.author,
          r."createdAt",
          p.name as "productName"
        FROM reviews r
        INNER JOIN products p ON r."productId" = p.id
        WHERE r.author = '${authorFilter}'
        ORDER BY r."createdAt" DESC
      `;

        let queryResults: Record<string, unknown>[] = [];
        const db = new Database(getDbPath());
        try {
          db.exec(query);
          try {
            queryResults = db
              .prepare(
                `SELECT
                r.id,
                r."productId",
                r.content,
                r.author,
                r."createdAt",
                p.name as "productName"
              FROM reviews r
              INNER JOIN products p ON r."productId" = p.id
              WHERE r.author = '${authorFilter}'
              ORDER BY r."createdAt" DESC`
              )
              .all() as Record<string, unknown>[];
          } catch {
            queryResults = [];
          }
        } catch {
          queryResults = [];
        } finally {
          db.close();
        }

        reviews = queryResults
          .map((row: Record<string, unknown>) => {
            const result: Record<string, unknown> = {};
            for (const key in row) {
              const value = row[key];
              if (
                typeof value === "string" &&
                (value.toLowerCase().includes("qkb{") ||
                  value.toLowerCase().includes("qkb{"))
              ) {
                continue;
              }
              result[key] = value;
            }
            return result;
          })
          .filter((row) => Object.keys(row).length > 0);
      } else {
        const safeReviews = await prisma.review.findMany({
          include: {
            product: {
              select: { name: true },
            },
          },
          orderBy: { createdAt: "desc" },
        });

        reviews = safeReviews.map((r) => ({
          id: r.id,
          productId: r.productId,
          content: r.content,
          author: r.author,
          createdAt: r.createdAt,
          productName: r.product.name,
        }));
      }

      const response: {
        reviews: Record<string, unknown>[];
        authors: string[];

        message?: string;
      } = {
        reviews,
        authors: distinctAuthors,
      };






      return NextResponse.json(response);
    } catch (error) {
      logger.error(
        { err: error, route: "/api/admin/reviews" },
        "Error fetching reviews"
      );
      return NextResponse.json(
        { error: "Failed to fetch reviews" },
        { status: 500 }
      );
    }
  }
);

